const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');

const modules = [
  'lib/client/sse_parser.js',
  'lib/client/ndjson_event_parser.js',
  'lib/client/chat_event_state.js',
  'lib/client/chat_stream_client.js',
  'lib/client/chat_ui_model.js',
  'lib/client/chat_ui_fixtures.js',
  'lib/client/chat_ui_app.js',
];

const dependencyMap = {
  'lib/client/chat_stream_client.js': {
    './sse_parser': 'lib/client/sse_parser.js',
    './ndjson_event_parser': 'lib/client/ndjson_event_parser.js',
    './chat_event_state': 'lib/client/chat_event_state.js',
  },
  'lib/client/chat_ui_app.js': {
    './chat_stream_client': 'lib/client/chat_stream_client.js',
    './chat_event_state': 'lib/client/chat_event_state.js',
    './chat_ui_model': 'lib/client/chat_ui_model.js',
    './chat_ui_fixtures': 'lib/client/chat_ui_fixtures.js',
  },
};

function moduleSource(filename) {
  const source = fs.readFileSync(path.join(root, filename), 'utf8');
  return JSON.stringify(source);
}

const moduleEntries = modules.map((filename) => {
  const deps = dependencyMap[filename] || {};
  return `${JSON.stringify(filename)}: [function(require, module, exports) {\n`
    + `eval(${moduleSource(filename)} + "\\n//# sourceURL=${filename}");\n`
    + `}, ${JSON.stringify(deps)}]`;
});

const bundle = `/* Generated by scripts/build_client_bundle.js. Do not edit by hand. */\n`
  + `(function () {\n`
  + `  const modules = {\n    ${moduleEntries.join(',\n    ')}\n  };\n`
  + `  const cache = {};\n`
  + `  function requireModule(id) {\n`
  + `    if (cache[id]) return cache[id].exports;\n`
  + `    if (!modules[id]) throw new Error('Module not found: ' + id);\n`
  + `    const module = { exports: {} };\n`
  + `    cache[id] = module;\n`
  + `    const localRequire = (request) => {\n`
  + `      const mapped = modules[id][1][request];\n`
  + `      if (!mapped) throw new Error('Dependency not mapped: ' + request + ' from ' + id);\n`
  + `      return requireModule(mapped);\n`
  + `    };\n`
  + `    modules[id][0](localRequire, module, module.exports);\n`
  + `    return module.exports;\n`
  + `  }\n`
  + `  requireModule('lib/client/chat_ui_app.js');\n`
  + `})();\n`;

fs.writeFileSync(path.join(root, 'app.bundle.js'), bundle, 'utf8');
console.log('wrote app.bundle.js');
